insert into public.content_collections(segment,collection,items) values('agency','services','[{"slug":"strategie","title":{"fr":"Stratégie de marque","en":"Brand strategy"},"copy":{"fr":"Clarifier votre public, votre positionnement et votre proposition de valeur.","en":"Clarify your audience, your positioning and your value proposition."},"items":{"fr":["Entretiens de cadrage","Carte des publics","Plateforme de marque"],"en":["Discovery interviews","Audience map","Brand platform"]}},{"slug":"branding","title":{"fr":"Identité & branding","en":"Identity & branding"},"copy":{"fr":"Créer un langage visuel que l’on reconnaît, du premier contact au quotidien.","en":"Create a visual language people recognise, from first contact to everyday use."},"items":{"fr":["Direction artistique","Identité visuelle","Guide de marque"],"en":["Art direction","Visual identity","Brand guidelines"]}},{"slug":"marketing","title":{"fr":"Marketing digital","en":"Digital marketing"},"copy":{"fr":"Relier les canaux à un objectif et organiser la mesure.","en":"Connect your channels to an objective and organise how you measure it."},"items":{"fr":["Audit des canaux","Plan de campagne","Cadre de suivi"],"en":["Channel audit","Campaign plan","Tracking framework"]}},{"slug":"social-media","title":"Social media","copy":{"fr":"Construire une présence éditoriale cohérente et une conversation utile.","en":"Build a coherent editorial presence and a useful conversation."},"items":{"fr":["Ligne éditoriale","Calendrier","Formats de publication"],"en":["Editorial line","Calendar","Post formats"]}},{"slug":"performance","title":{"fr":"Campagnes & performance","en":"Campaigns & performance"},"copy":{"fr":"Préparer des campagnes ciblées, des variantes et des critères de décision.","en":"Prepare targeted campaigns, variations and decision criteria."},"items":{"fr":["Brief de campagne","Créations publicitaires","Plan de mesure"],"en":["Campaign brief","Ad creatives","Measurement plan"]}},{"slug":"web-design","title":"Web design","copy":{"fr":"Donner à votre site une composition claire et une identité forte.","en":"Give your website a clear layout and a strong identity."},"items":{"fr":["Architecture de pages","Maquettes responsive","Prototype"],"en":["Page architecture","Responsive mock-ups","Prototype"]}},{"slug":"web-development","title":{"fr":"Développement web","en":"Web development"},"copy":{"fr":"Transformer les parcours validés en pages et fonctionnalités utilisables.","en":"Turn validated journeys into usable pages and features."},"items":{"fr":["Intégration","Recette fonctionnelle","Documentation"],"en":["Front-end build","Functional testing","Documentation"]}},{"slug":"applications","title":"Applications","copy":{"fr":"Concevoir un outil adapté aux tâches de votre équipe ou de votre public.","en":"Design a tool shaped around the tasks of your team or your audience."},"items":{"fr":["Cadrage fonctionnel","Parcours","Version testable"],"en":["Functional scoping","Journeys","Testable version"]}},{"slug":"product-design","title":"Product design","copy":{"fr":"Définir un produit autour d’un usage, puis vérifier ses hypothèses.","en":"Define a product around a use, then test its assumptions."},"items":{"fr":["Priorisation","Prototype","Plan de tests"],"en":["Prioritisation","Prototype","Test plan"]}},{"slug":"ui-ux","title":"UI & UX","copy":{"fr":"Rendre chaque étape compréhensible et donner de la cohérence aux interfaces.","en":"Make every step clear and bring consistency to your interfaces."},"items":{"fr":["Recherche de besoins","Parcours","Composants"],"en":["Needs research","Journeys","Components"]}},{"slug":"video","title":{"fr":"Film & vidéo","en":"Film & video"},"copy":{"fr":"Raconter une idée avec une intention, un rythme et des images.","en":"Tell an idea with intention, rhythm and images."},"items":{"fr":["Synopsis","Préparation du tournage","Montage"],"en":["Synopsis","Shoot preparation","Editing"]}},{"slug":"photographie","title":{"fr":"Photographie","en":"Photography"},"copy":{"fr":"Composer une série d’images pour une marque, un produit ou une histoire.","en":"Compose a series of images for a brand, a product or a story."},"items":{"fr":["Moodboard","Liste de prises de vue","Sélection"],"en":["Moodboard","Shot list","Selection"]}},{"slug":"contenus","title":{"fr":"Création de contenus","en":"Content creation"},"copy":{"fr":"Organiser les idées et les décliner pour les bons supports.","en":"Organise ideas and adapt them to the right media."},"items":{"fr":["Angle éditorial","Textes","Kit de formats"],"en":["Editorial angle","Copy","Format kit"]}},{"slug":"ia-automatisation","title":{"fr":"IA & automatisation","en":"AI & automation"},"copy":{"fr":"Identifier les tâches répétitives et concevoir un parcours avec contrôle humain.","en":"Identify repetitive tasks and design a journey with human control."},"items":{"fr":["Cartographie","Prototype","Règles de validation"],"en":["Process map","Prototype","Validation rules"]}},{"slug":"crm","title":{"fr":"CRM & opérations","en":"CRM & operations"},"copy":{"fr":"Relier le suivi des contacts au travail quotidien des équipes.","en":"Connect contact tracking to your teams’ daily work."},"items":{"fr":["Carte du processus","Structure de suivi","Accompagnement"],"en":["Process map","Tracking structure","Support"]}},{"slug":"croissance","title":"Business growth","copy":{"fr":"Aligner l’offre, la communication et le parcours commercial.","en":"Align your offer, your communication and your sales journey."},"items":{"fr":["Diagnostic","Priorités","Plan d’action"],"en":["Diagnosis","Priorities","Action plan"]}}]'::jsonb) on conflict do nothing;
insert into public.content_collections(segment,collection,items) values('agency','brands','[{"slug":"focus-com","name":"Focus-Com","sector":"Communication & image","summary":{"fr":"Une charte graphique bleu électrique pour une agence au service de l’image : logo, couleurs, typographie, papeterie, vêtements et supports média.","en":"An electric-blue brand guide for an image-focused agency: logo, colours, typography, stationery, apparel and media assets."},"deliverables":{"fr":["Logo & règles d’usage","Palette & typographie","Papeterie","Vêtements & goodies","Maquettes média"],"en":["Logo & usage rules","Palette & typography","Stationery","Apparel & merchandise","Media mock-ups"]},"pages":["local:brand/focus-1","local:brand/focus-2","local:brand/focus-3","local:brand/focus-4","local:brand/focus-5","local:brand/focus-6","local:brand/focus-7","local:brand/focus-8"]},{"slug":"g-traf","name":"G-TRAF+","sector":{"fr":"Travaux publics & fournitures","en":"Public works & supplies"},"summary":{"fr":"L’identité d’une entreprise guinéenne de travaux et de fournitures : emblème, chantiers, signalétique, véhicules et réseaux sociaux.","en":"The identity of a Guinean works and supplies company: emblem, sites, signage, vehicles and social media."},"deliverables":{"fr":["Logo & emblème","Signalétique de chantier","Uniformes & EPI","Flotte & affichage","Réseaux sociaux"],"en":["Logo & emblem","Site signage","Uniforms & PPE","Fleet & billboards","Social media"]},"pages":["local:brand/gtraf-1","local:brand/gtraf-2","local:brand/gtraf-3","local:brand/gtraf-4","local:brand/gtraf-5","local:brand/gtraf-6","local:brand/gtraf-7","local:brand/gtraf-8"]},{"slug":"bet224","name":"Bet224","sector":{"fr":"Paris sportifs","en":"Sports betting"},"summary":{"fr":"Une identité jaune et noire pleine d’énergie : « Le prochain, c’est toi ». Gadgets, maillots, véhicules, affichage et application.","en":"A high-energy yellow and black identity: “You’re next”. Merchandise, jerseys, vehicles, billboards and