insert into public.content_collections(segment,collection,items) values('agency','series','[{"slug":"mode","title":{"fr":"Éditorial mode","en":"Fashion editorial"},"copy":{"fr":"Direction artistique, stylisme et lumière naturelle dans des lieux d’exception.","en":"Art direction, styling and natural light in exceptional venues."},"photos":["local:work/shoot-09181","local:work/shoot-09258","local:work/shoot-09276","local:work/shoot-09693","local:work/shoot-09697","local:work/shoot-09703","local:work/shoot-09724","local:work/shoot-09849","local:work/shoot-09862","local:work/shoot-09872","local:work/shoot-09894","local:work/shoot-09170"]},{"slug":"sport","title":{"fr":"Reportage football","en":"Football reportage"},"copy":{"fr":"Au bord du terrain, au cœur de l’émotion : avant, pendant et après le match.","en":"On the touchline, in the thick of the emotion: before, during and after the match."},"photos":["local:work/shoot-00557","local:work/shoot-00447","local:work/shoot-00549","local:work/shoot-09841","local:work/shoot-09850","local:work/shoot-00064","local:work/shoot-09891","local:work/shoot-09990"]},{"slug":"lieux","title":{"fr":"Lieux & hôtellerie","en":"Venues & hospitality"},"copy":{"fr":"Salles, salons et détails : des images qui donnent envie de réserver.","en":"Rooms, lounges and details: images that make people want to book."},"photos":["local:work/shoot-09296","local:work/shoot-09287","local:work/shoot-09285","local:work/shoot-09409","local:work/shoot-09419","local:work/shoot-09333"]}]'::jsonb) on conflict do nothing;
insert into public.content_collections(segment,collection,items) values('academy','courses','[{"slug":"communication-digitale","title":{"fr":"Communication digitale — Stratégie de contenu","en":"Digital communication — Content strategy"},"category":{"fr":"Stratégie","en":"Strategy"},"track":{"fr":"Marketing digital & croissance","en":"Digital marketing & growth"},"level":{"fr":"Fondamental","en":"Foundation"},"hours":14,"format":{"fr":"2 jours · 14 h","en":"2 days · 14 h"},"goal":{"fr":"Définir une stratégie de contenu cohérente et construire un calendrier éditorial opérationnel.","en":"Define a coherent content strategy and build a working editorial calendar."},"why":{"fr":"Avant de créer quoi que ce soit, il faut comprendre pourquoi, pour qui et comment communiquer.","en":"Before creating anything, you need to understand why, for whom and how to communicate."},"project":{"fr":"Construire le calendrier éditorial de votre entreprise.","en":"Build your company’s editorial calendar."},"program":{"fr":["Principes de la communication institutionnelle digitale","Identifier sa cible et définir ses objectifs","Créer un calendrier éditorial mensuel","Rédiger des posts engageants adaptés au public guinéen","Comprendre les algorithmes : Facebook, Instagram, TikTok","Adapter le ton et le message à chaque plateforme"],"en":["Principles of institutional digital communication","Identify your audience and set your objectives","Create a monthly editorial calendar","Write engaging posts for a Guinean audience","Understand the algorithms: Facebook, Instagram, TikTok","Adapt tone and message to each platform"]},"outcomes":{"fr":["Certificat Smartsell","Supports PDF : cours + exercices","Suivi de 30 jours après la formation"],"en":["Smartsell certificate","PDF materials: lessons + exercises","30-day follow-up after training"]},"photo":"local:academy-room","lessons":[{"title":{"fr":"Pour qui, pourquoi ?","en":"For whom, and why?"},"copy":{"fr":"Une stratégie commence par une cible précise et un objectif mesurable. Une clinique qui veut des rendez-vous ne communique pas comme une boutique qui veut des visites : le public, le ton et le canal changent.","en":"A strategy starts with a precise audience and a measurable objective. A clinic that wants appointments does not communicate like a shop that wants visits: audience, tone and channel all change."},"exercise":{"fr":"Écrivez votre cible principale et l’action que vous attendez d’elle ce mois-ci.","en":"Write down your main audience and the action you expect from it this month."},"question":{"fr":"Par quoi commence une stratégie de contenu ?","en":"What does a content strategy start with?"},"options":{"fr":["Une cible et un objectif","Un nouveau logo","Publier tous les jours"],"en":["An audience and an objective","A new logo","Posting every day"]},"answer":0},{"title":{"fr":"Le calendrier éditorial","en":"The editorial calendar"},"copy":{"fr":"Le calendrier relie chaque publication à un thème, un format, une date et un responsable. Il évite l’improvisation et garde une présence régulière, même pendant les semaines chargées.","en":"The calendar links each post to a theme, a format, a date and an owner. It prevents improvisation and keeps a steady presence, even during busy weeks."},"exercise":{"fr":"Planifiez quatre semaines : un thème par semaine et trois formats différents.","en":"Plan four weeks: one theme per week and three different formats."},"question":{"fr":"Que doit préciser chaque ligne du calendrier ?","en":"What should each calendar line specify?"},"options":{"fr":["Thème, format, date et responsable","Seulement la date","Le nombre de likes espéré"],"en":["Theme, format, date and owner","Only the date","The number of likes hoped for"]},"answer":0},{"title":{"fr":"Chaque réseau a sa langue","en":"Every network has its language"},"copy":{"fr":"Facebook favorise la conversation, Instagram l’image soignée, TikTok le rythme et l’authenticité. Le même message se décline : on adapte la durée, le visuel et l’accroche à chaque algorithme.","en":"Facebook favours conversation, Instagram polished visuals, TikTok pace and authenticity. The same message gets adapted: length, visual and hook change with each algorithm."},"exercise":{"fr":"Déclinez une même annonce pour Facebook, Instagram et TikTok.","en":"Adapt one announcement for Facebook, Instagram and TikTok."},"question":{"fr":"Que faut-il adapter d’un réseau à l’autre ?","en":"What must change from one network to another?"},"options":{"fr":["Le format, l’accroche et la durée","Rien, on copie-colle","Uniquement la couleur"],"en":["Format, hook and length","Nothing, just copy and paste","Only the colour"]},"answer":0}]},{"slug":"redaction-web","title":{"fr":"Rédaction institutionnelle pour le web","en":"Institutional writing for the web"},"category":{"fr":"Rédaction","en":"Writing"},"track":{"fr":"Marketing digital & croissance","en":"Digital marketing & growth"},"level":{"fr":"Fondamental","en":"Foundation"},"hours":7,"format":{"fr":"1 jour · 7 h","en":"1 day · 7 h"},"goal":{"fr":"Produire des textes clairs, lisibles et efficaces pour le web et les réseaux sociaux.","en":"Produce clear, readable and effective copy for the web and social media."},"why":{"fr":"Savoir écrire pour le web est la compétence de base avant tout outil de création.","en":"Writing for the web is the core skill before any creative tool."},"project":{"fr":"Rédiger trois contenus web pour votre organisation.","en":"Write three web pieces for your organisation."},"program":{"fr":["Lisibilité, hiérarchie et référencement naturel","Structurer un article, un communiqué, un post","Titres accrocheurs et appels à l’action","Écrire pour un réseau social ou pour un site","Adapter son style au secteur : santé, éducation, BTP…"],"en":["Readability, hierarchy and SEO","Structure an article, a press release, a post","Catchy headlines and calls to action","Writing for social media vs. a website","Adapt your style to the sector: health, education, construction…"]},"outcomes":{"fr":["Certificat Smartsell","Supports PDF : cours + exercices","Suivi de 30 jours après la formation"],"en":["Smartsell certificate","PDF materials: lessons + exercises","30-day follow-up after training"]},"photo":"local:academy-home","lessons":[{"title":{"fr":"L’essentiel en premier","en":"Lead with what matters"},"copy":{"fr":"Sur écran, on lit en diagonale. Le message principal se place dans le titre et la première phrase ; les détails suivent, en paragraphes courts et intertitres.","en":"On screen, people skim. The main message goes in the headline and first sentence; details follow in short paragraphs and subheadings."},"exercise":{"fr":"Réécrivez un texte existant en mettant l’information clé en premier.","en":"Rewrite an existing text with the key information first."},"question":{"fr":"Où placer l’information principale ?","en":"Where does the main information go?"},"options":{"fr":["Dans le titre et la première phrase","À la fin, en conclusion","Dans une note de bas de page"],"en":["In the headline and first sentence","At the end, as a conclusion","In a footnote"]},"answer":0},{"title":{"fr":"Des titres qui donnent envie","en":"Headlines that pull readers in"},"copy":{"fr":"Un bon titre promet un bénéfice concret et reste honnête. Il annonce ce que le lecteur va apprendre ou obtenir, sans effet trompeur.","en":"A good headline promises a concrete benefit and stays honest. It tells readers what they will learn or get, without misleading tricks."},"exercise":{"fr":"Proposez cinq titres pour une même actualité.","en":"Draft five headlines for the same news item."},"question":{"fr":"Qu’est-ce qui rend un titre efficace ?","en":"What makes a headline effective?"},"options":{"fr":["Un bénéfice clair et honnête","Le plus de mots possible","Un suspense sans rapport"],"en":["A clear, honest benefit","As many words as possible","Unrelated suspense"]},"answer":0},{"title":{"fr":"Toujours finir par une action","en":"Always end with an action"},"copy":{"fr":"Chaque contenu guide vers une étape suivante : appeler, réserver, s’inscrire, écrire sur WhatsApp. Un appel à l’action unique et précis convertit mieux que plusieurs choix.","en":"Every piece leads to a next step: call, book, sign up, message on WhatsApp. One precise call to action converts better than several choices."},"exercise":{"fr":"Ajoutez un appel à l’action précis à vos trois contenus.","en":"Add one precise call to action to your three pieces."},"question":{"fr":"Combien d’appels à l’action par contenu ?","en":"How many calls to action per piece?"},"options":{"fr":["Un seul, précis","Le plus possible","Aucun"],"en":["One, precise","As many as possible","None"]},"answer":0}]},{"slug":"canva-pro","title":{"fr":"Canva Pro — Visuels professionnels","en":"Canva Pro — Professional visuals"},"category":"Design","track":{"fr":"Marketing digital & croissance","en":"Digital marketing & growth"},"level":{"fr":"Opérationnel","en":"Operational"},"hours":14,"format":{"fr":"2 jours · 14 h","en":"2 days · 14 h"},"goal":{"fr":"Créer des visuels professionnels pour tous les supports digitaux, sans formation en design.","en":"Create professional visuals for every digital channel, with no design background."},"why":{"fr":"Une fois la stratégie posée et les textes maîtrisés, on passe à la création visuelle.","en":"Once the strategy is set and the copy is mastered, it is time for visuals."},"project":{"fr":"Produire 5 visuels prêts à publier.","en":"Produce 5 ready-to-publish visuals."},"program":{"fr":["Prise en main de l’interface Canva Pro","Couleurs, typographie, espacement","Posts, stories, bannières et couvertures","Infographies simples et percutantes","Templates et kit de marque","Un kit visuel complet pour votre organisation"],"en":["Getting started with Canva Pro","Colour, typography, spacing","Posts, stories, banners and covers","Simple, striking infographics","Templates and brand kit","A complete visual kit for your organisation"]},"outcomes":{"fr":["Certificat Smartsell","Supports PDF : cours + exercices","Suivi de 30 jours après la formation"],"en":["Smartsell certificate","PDF materials: lessons + exercises","30-day follow-up after training"]},"photo":"local:agency-designer","lessons":[{"title":{"fr":"La hiérarchie visuelle","en":"Visual hierarchy"},"copy":{"fr":"Un visuel professionnel se lit dans l’ordre : titre, sous-titre, contenu, appel à l’action. La taille, le contraste et l’espace guident l’œil.","en":"A professional visual reads in order: headline, subheading, content, call to action. Size, contrast and space guide the eye."},"exercise":{"fr":"Créez un visuel promo en respectant cet ordre de lecture.","en":"Create a promo visual that follows this reading order."},"question":{"fr":"Qu’est-ce qui guide l’œil ?","en":"What guides the eye?"},"options":{"fr":["Taille, contraste et espace","Le nombre de couleurs","Les effets 3D"],"en":["Size, contrast and space","The number of colours","3D effects"]},"answer":0},{"title":{"fr":"Le kit de marque","en":"The brand kit"},"copy":{"fr":"Logo, palette et polices enregistrés dans Canva garantissent la cohérence : toute l’équipe crée avec les mêmes éléments.","en":"Logo, palette and fonts saved in Canva guarantee consistency: the whole team creates with the same elements."},"exercise":{"fr":"Configurez le kit de marque de votre organisation.","en":"Set up your organisation’s brand kit."},"question":{"fr":"À quoi sert le kit de marque ?","en":"What is the brand kit for?"},"options":{"fr":["À rester cohérent","À changer de style chaque jour","À éviter les templates"],"en":["Staying consistent","Changing style every day","Avoiding templates"]},"answer":0},{"title":{"fr":"Les bons formats","en":"The right formats"},"copy":{"fr":"Un post carré, une story verticale, une bannière horizontale : chaque emplacement a son format. Créer au bon format évite les recadrages qui coupent le message.","en":"A square post, a vertical story, a horizontal banner: each placement has its f