t react in the heat"},"copy":{"fr":"Le premier réflexe est de vérifier les faits et de désigner une seule voix. Une réponse précipitée nourrit souvent la crise au lieu de l’éteindre.","en":"The first reflex is to check the facts and name a single spokesperson. A rushed reply often feeds the crisis instead of calming it."},"exercise":{"fr":"Écrivez la procédure en trois étapes de votre organisation.","en":"Write your organisation’s three-step procedure."},"question":{"fr":"Quel est le premier réflexe ?","en":"What is the first reflex?"},"options":{"fr":["Vérifier les faits et désigner un porte-parole","Supprimer tous les commentaires","Répondre à chacun immédiatement"],"en":["Check the facts and name a spokesperson","Delete every comment","Reply to everyone immediately"]},"answer":0},{"title":{"fr":"Le message de crise","en":"The crisis message"},"copy":{"fr":"Reconnaître, expliquer ce qui est fait, indiquer quand on reviendra vers le public : un message court, humain et factuel rassure.","en":"Acknowledge, explain what is being done, say when you will report back: a short, human, factual message reassures."},"exercise":{"fr":"Rédigez un post officiel en réponse à une rumeur.","en":"Draft an official post responding to a rumour."},"question":{"fr":"Qu’est-ce qui rassure le public ?","en":"What reassures the public?"},"options":{"fr":["Un message court, humain et factuel","Le silence total","Un message agressif"],"en":["A short, human, factual message","Total silence","An aggressive message"]},"answer":0},{"title":{"fr":"Surveiller pour anticiper","en":"Monitor to anticipate"},"copy":{"fr":"Une veille simple — alertes, mots-clés, mentions — permet de repérer un sujet sensible avant qu’il ne devienne viral.","en":"Simple monitoring — alerts, keywords, mentions — spots a sensitive topic before it goes viral."},"exercise":{"fr":"Listez dix mots-clés à surveiller pour votre organisation.","en":"List ten keywords to monitor for your organisation."},"question":{"fr":"À quoi sert la veille ?","en":"What is monitoring for?"},"options":{"fr":["À repérer un sujet avant qu’il explose","À publier plus","À rien en période calme"],"en":["Spotting a topic before it blows up","Publishing more","Nothing in quiet times"]},"answer":0}]},{"slug":"infographie-canva","title":{"fr":"Infographie & Canva — Du fondamental au niveau agence","en":"Graphic design & Canva — From basics to agency level"},"category":"Design","track":{"fr":"Infographie & Canva","en":"Graphic design & Canva"},"level":{"fr":"Tous niveaux","en":"All levels"},"format":{"fr":"8 modules · 4 semaines","en":"8 modules · 4 weeks"},"goal":{"fr":"Comprendre les règles du design, maîtriser Canva et l’IA, puis produire comme une agence.","en":"Understand design rules, master Canva and AI, then produce like an agency."},"why":{"fr":"Un designer n’est pas quelqu’un qui « fait joli » : il résout un problème visuel pour une cible.","en":"A designer does not just “make it pretty”: they solve a visual problem for an audience."},"project":{"fr":"Un pack de 12 visuels pour une entreprise et un mini portfolio validé.","en":"A 12-visual pack for a company and an approved mini portfolio."},"program":{"fr":["Les règles fondamentales de l’infographie","Couleurs, typographies & cohérence de marque","Canva de A à Z","Canva pour Facebook, Instagram et WhatsApp","L’IA pour créer plus vite","L’IA dans Canva : Magic Write, Magic Design","Création de contenu en série","Mini portfolio & validation finale"],"en":["The fundamental rules of graphic design","Colour, type & brand consistency","Canva from A to Z","Canva for Facebook, Instagram and WhatsApp","AI to create faster","AI in Canva: Magic Write, Magic Design","Batch content creation","Mini portfolio & final review"]},"outcomes":{"fr":["Un mini style guide de marque","Une mini campagne : affiche, story, post, statut","Un portfolio exporté proprement"],"en":["A mini brand style guide","A mini campaign: poster, story, post, status","A cleanly exported portfolio"]},"photo":"local:agency-tablet","lessons":[{"title":{"fr":"La mentalité du designer","en":"The designer’s mindset"},"copy":{"fr":"Observer, simplifier, structurer, rester cohérent : ces quatre piliers guident chaque visuel. On travaille pour une cible, pas pour ses goûts personnels.","en":"Observe, simplify, structure, stay consistent: these four pillars guide every visual. You design for an audience, not for your own taste."},"exercise":{"fr":"Créez 2 visuels avant/après sur un même thème.","en":"Create 2 before/after visuals on one theme."},"question":{"fr":"Pour qui travaille le designer ?","en":"Who does the designer work for?"},"options":{"fr":["Pour une cible","Pour lui-même","Pour les autres designers"],"en":["For an audience","For themselves","For other designers"]},"answer":0},{"title":{"fr":"Pas d’arc-en-ciel","en":"No rainbows"},"copy":{"fr":"Une palette courte, deux polices maximum et une structure répétée : la cohérence est le secret des marques fortes et l’erreur la plus fréquente sur les pages locales.","en":"A short palette, two fonts at most and a repeated structure: consistency is the secret of strong brands and the most common mistake on local pages."},"exercise":{"fr":"Créez un mini style guide : palette, polices, mise en page.","en":"Create a mini style guide: palette, fonts, layout."},"question":{"fr":"Combien de polices au maximum ?","en":"How many fonts at most?"},"options":{"fr":["Deux","Cinq","Autant qu’on veut"],"en":["Two","Five","As many as you like"]},"answer":0},{"title":{"fr":"Produire en série","en":"Producing in batches"},"copy":{"fr":"Thème, texte, design, déclinaisons : la méthode batch permet de produire vite sans perdre en qualité, et de travailler sereinement avec les retours du client.","en":"Theme, copy, design, variations: the batch method lets you produce fast without losing quality, and handle client feedback calmly."},"exercise":{"fr":"Déclinez une série de 6 visuels à partir d’un modèle.","en":"Create a series of 6 visuals from one template."},"question":{"fr":"Quel est l’ordre de la méthode batch ?","en":"What is the batch method order?"},"options":{"fr":["Thème, texte, design, déclinaisons","Design, puis on verra","Déclinaisons d’abord"],"en":["Theme, copy, design, variations","Design, then we’ll see","Variations first"]},"answer":0}]},{"slug":"creation-contenu-ia","title":{"fr":"Création de contenu & IA — Intensif","en":"Content creation & AI — Intensive"},"category":{"fr":"Vidéo","en":"Video"},"track":{"fr":"Création de contenu & IA","en":"Content creation & AI"},"level":{"fr":"Tous niveaux","en":"All levels"},"hours":12,"format":{"fr":"3 semaines · 6 séances de 2 h","en":"3 weeks · 6 sessions of 2 h"},"goal":{"fr":"Transformer son smartphone en studio de production et lancer son activité de créateur.","en":"Turn your smartphone into a production studio and launch your creator business."},"why":{"fr":"Domptez l’IA : passez de créateur de contenu à professionnel rentable en trois semaines.","en":"Tame AI: go from content creator to profitable professional in three weeks."},"project":{"fr":"Un plan de communication complet pour un client : calendrier, visuels, vidéos et stratégie IA.","en":"A complete communication plan for a client: calendar, visuals, videos and AI strategy."},"program":{"fr":["Semaine 1 · Visuels avec Canva et l’IA","Semaine 2 · Montage mobile avec CapCut et l’IA","Semaine 3 · Marketing digital et lancement en freelance","Bonus · Ebook IA & création de contenu"],"en":["Week 1 · Visuals with Canva and AI","Week 2 · Mobile editing with CapCut and AI","Week 3 · Digital marketing and going freelance","Bonus · AI & content creation ebook"]},"outcomes":{"fr":["Un portfolio de 5 visuels","Un spot publicitaire de 30 secondes","Votre offre de services et votre brandbook personnel"],"en":["A portfolio of 5 visuals","A 30-second ad spot","Your service offer and personal brandbook"]},"photo":"local:social-night","lessons":[{"title":{"fr":"Visuels chocs avec l’IA","en":"Striking visuals with AI"},"copy":{"fr":"Canva et ses outils IA génèrent images, arrière-plans et pistes de logo. On garde la main sur la composition, les couleurs et la typographie.","en":"Canva and its AI tools generate images, backgrounds and logo ideas. You stay in charge of composition, colour and type."},"exercise":{"fr":"Créez 3 posts Facebook et 2 posts LinkedIn.","en":"Create 3 Facebook posts and 2 LinkedIn posts."},"question":{"fr":"Qui décide de la composition finale ?","en":"Who decides the final composition?"},"options":{"fr":["Vous","L’IA","Le hasard"],"en":["You","The AI","Chance"]},"answer":0},{"title":{"fr":"Vidéos virales et rentables","en":"Viral, profitable videos"},"copy":{"fr":"Storytelling court, transitions, sous-titres automatiques et effets IA de CapCut : on produit des Reels et TikTok percutants depuis son téléphone.","en":"Short storytelling, transitions, auto captions and CapCut’s AI effects: produce punchy Reels and TikToks from your phone."},"exercise":{"fr":"Réalisez un spot de 30 secondes pour une entreprise fictive.","en":"Make a 30-second spot for a fictional company."},"question":{"fr":"Quel outil sert au montage mobile ?","en":"Which tool is used for mobile editing?"},"options":{"fr":["CapCut","Un tableur","Un traitement de texte"],"en":["CapCut","A spreadsheet","A word processor"]},"answer":0},{"title":{"fr":"Se lancer en freelance","en":"Going freelance"},"copy":{"fr":"Profil LinkedIn optimisé, offre de services claire, prix justifié et brandbook personnel : on se présente comme un professionnel.","en":"An optimised LinkedIn profile, a clear service offer, a justified price and a personal brandbook: present yourself as a professional."},"exercise":{"fr":"Rédigez votre offre de services et fixez vos prix.","en":"Write your service offer and set your prices."},"question":{"fr":"Que faut-il pour se présenter en pro ?","en":"What do you need to present yourself as a pro?"},"options":{"fr":["Une offre claire et un profil soigné","Des prix cachés","Aucune présentation"],"en":["A clear offer and a polished profile","Hidden prices","No introduction"]},"answer":0}]},{"slug":"motion-design-claude","title":{"fr":"Motion design avec Claude","en":"Motion design with Claude"},"category":{"fr":"IA créative","en":"Creative AI"},"track":{"fr":"IA créative","en":"Creative AI"},"level":{"fr":"Niveau 3","en":"Level 3"},"format":{"fr":"7 parties · 7 prompts maîtres","en":"7 parts · 7 master prompts"},"goal":{"fr":"Briefer et produire des vidéos SaaS, corporate et cinématiques, du brief au rendu image par image.","en":"Brief and produce SaaS, corporate and cinematic videos, from brief to frame-by-frame render."},"why":{"fr":"Votre valeur se déplace : elle n’est plus dans le geste sur la timeline, mais dans le brief.","en":"Your value moves: it is no longer in the timeline gesture, but in the brief."},"project":{"fr":"Un film SaaS de 40 secondes traité de bout en bout.","en":"A 40-second SaaS film produced end to end."},"program":{"fr":["La chaîne : brief, scène programmée, rendu, son, assemblage","Quatre lexiques pour briefer","Le brief complet et le protocole de captures","Structure d’une vidéo SaaS de 40 secondes","Trois styles de montage et les rushes","Sound design seconde par seconde","Corriger, livrer, éviter les dix pièges"],"en":["The pipeline: brief, coded scene, render, sound, assembly","Four vocabularies to brief","The full brief and the screenshot protocol","Structure of a 40-second SaaS video","Three editing styles and the rushes","Sound design second by second","Fix, deliver, avoid the ten pitfalls"]},"outcomes":{"fr":["Les 7 prompts maîtres","Une checklist de production","Un exercice de validation"],"en":["The 7 master prompts","A production checklist","A validation exercise"]},"photo":"local:prod-lens","lessons":[{"title":{"fr":"Un atelier de rendu","en":"A rendering workshop"},"copy":{"fr":"Claude ne déplace pas des calques : il programme une scène où chaque élément est une fonction du temps, puis la rend image par image. Ce qui n’est pas décrit n’existe pas.","en":"Claude does not move layers: it codes a scene where every element is a function of time, then renders it frame by frame. What is not described does not exist."},"exercise":{"fr":"Décrivez une scène de 5 secondes avec ses positions et opacités.","en":"Describe a 5-second scene with its positions and opacities."},"question":{"fr":"Où se décide la vidéo ?","en":"Where is the video decided?"},"options":{"fr":["Dans le brief","À la souris","Au hasard"],"en":["In the brief","With the mouse","At random"]},"answer":0},{"title":{"fr":"Le découpage temporel","en":"The time breakdown"},"copy":{"fr":"Une vidéo SaaS de 40 secondes se découpe en scènes avec leurs secondes : accroche, problème, produit, preuve, appel à l’action. À 30 images par seconde, cela fait 1 200 images.","en":"A 40-second SaaS video breaks into timed scenes: hook, problem, product, proof, call to action. At 30 frames per second, that is 1,200 frames."},"exercise":{"fr":"Découpez votre film en scènes avec leurs secondes.","en":"Break your film into timed scenes."},"question":{"fr":"Combien d’images pour 40 s à 30 i/s ?","en":"How many frames for 40 s at 30 fps?"},"options":{"fr":["1 200","400","30"],"en":["1,200","400","30"]},"answer":0},{"title":{"fr":"La bande son écrite","en":"The written soundtrack"},"copy":{"fr":"Whoosh, impacts, nappes : chaque effet est fabriqué et placé à une seconde précise. La bande son s’écrit au même titre que l’image.","en":"Whooshes, impacts, pads: each effect is made and placed at a precise second. The soundtrack is written just like the image."},"exercise":{"fr":"Placez cinq effets sonores sur votre découpage.","en":"Place five sound effects on your breakdown."},"question":{"fr":"Comment naît la bande son ?","en":"How is the soundtrack made?"},"options":{"fr":["Elle est écrite et synthétisée","Elle est téléchargée au hasard","Elle est facultative"],"en":["It is written and synthesised","It is downloaded at random","It is optional"]},"answer":0}]},{"slug":"garder-le-meme-visage","title":{"fr":"Garder le même visage","en":"Keeping the same face"},"category":{"fr":"IA créative","en":"Creative AI"},"track":{"fr":"IA créative","en":"Creative AI"},"level":{"fr":"Avancé","en":"Advanced"},"format":{"fr":"7 modules · prompts de référence","en":"7 modules · reference prompts"},"goal":{"fr":"Générer images, vidéos et signatures d’un sujet réel sans jamais déformer son visage.","en":"Generate images, videos and signatures of a real person without ever distorting their face."},"why":{"fr":"Un visage ne se décrit pas, il se montre : moins l’outil voit, plus il invente.","en":"A face is not described, it is shown: the less the tool sees, the more it invents."},"project":{"fr":"Une image fidèle, son clip court et la signature visuelle d’un sujet réel.","en":"A faithful image, its short clip and the visual signature of a real subject."},"program":{"fr":["La carte visuelle du sujet","Ranger la carte pour toute l’équipe","Le prompt en six blocs","Replacer le sujet dans un nouvel environnement","La grille des huit points","De l’image à la vidéo","La signature visuelle du sujet"],"en":["The subject’s visual map","Organising the map for the whole team","The six-block prompt","Placing the subject in a new environment","The eight-point grid","From image to video","The subject’s visual signature"]},"outcomes":{"fr":["Une méthode de contrôle géométrique","Des prompts de référence","Une pièce de communication signée"],"en":["A geometric quality-control method","Reference prompts","A signed communication piece"]},"photo":"unsplash:photo-1669040084821-097235fe53ff","lessons":[{"title":{"fr":"Pourquoi un visage se déforme","en":"Why a face gets distorted"},"copy":{"fr":"L’outil reconstruit un visage plausible : une seule photo, une photo floue ou une description en mots, et il invente un visage moyen, plus jeune et plus lisse.","en":"The tool rebuilds a plausible face: one photo, a blurry photo or a verbal description, and it invents an average, younger, smoother face."},"exercise":{"fr":"Constituez une carte visuelle de 10 vues d’un même sujet.","en":"Build a 10-view visual map of one subject."},"question":{"fr":"Comment éviter qu’il invente ?","en":"How do you stop it inventing?"},"options":{"fr":["Lui montrer plusieurs vues du sujet","Décrire le visage avec des adjectifs","Utiliser une seule photo"],"en":["Show it several views of the subject","Describe the face with adjectives","Use a single photo"]},"answer":0},{"title":{"fr":"Les distances avant la peau","en":"Distances before skin"},"copy":{"fr":"On reconnaît une personne d’abord aux distances entre ses traits, puis à son asymétrie et à ses signes particuliers. Nos contrôles sont géométriques, jamais esthétiques.","en":"We recognise someone first by the distances between features, then by asymmetry and distinctive marks. Our checks are geometric, never aesthetic."},"exercise":{"fr":"Contrôlez une image générée avec la grille des huit points.","en":"Check a generated image with the eight-point grid."},"question":{"fr":"Qu’est-ce qui compte le plus ?","en":"What matters most?"},"options":{"fr":["Les distances entre les traits","La couleur de peau","Le maquillage"],"en":["The distances between features","Skin colour","Make-up"]},"answer":0},{"title":{"fr":"Un changement à la fois","en":"One change at a time"},"copy":{"fr":"Décor, tenue, lumière, époque : on change un seul élément coûteux à la fois pour préserver le visage, puis on anime l’image en clip court.","en":"Setting, outfit, light, era: change one costly element at a time to preserve the face, then animate the image into a short clip."},"exercise":{"fr":"Replacez votre sujet dans un nouveau décor sans toucher au visage.","en":"Place your subject in a new setting without touching the face."},"question":{"fr":"Combien de changements coûteux à la fois ?","en":"How many costly changes at once?"},"options":{"fr":["Un seul","Tous","Trois"],"en":["Just one","All of them","Three"]},"answer":0}]},{"slug":"court-metrage-ia","title":{"fr":"Faire un court-métrage avec l’IA","en":"Making a short film with AI"},"category":{"fr":"IA créative","en":"Creative AI"},"track":{"fr":"IA créative","en":"Creative AI"},"level":{"fr":"Niveau 2","en":"Level 2"},"format":{"fr":"8 étapes · un film de 85 s en exemple","en":"8 steps · an 85-second example film"},"goal":{"fr":"Mener un court-métrage de l’écriture à la copie finale, avec des personnages dont on maîtrise le visage.","en":"Take a short film from script to final cut, with characters whose faces stay consistent."},"why":{"fr":"Un court-métrage IA se gagne avant la génération : on sait tenir un visage quatre secondes, alors on écrit des plans de quatre secondes.","en":"An AI short film is won before generation: we can hold a face for four seconds, so we write four-second shots."},"project":{"fr":"« Le Virage », un film de 85 secondes traité en exemple.","en":"“Le Virage”, an 85-second film used as the worked example."},"program":{"fr":["Écrire pour l’IA","Les bibles personnages et décors","Le découpage et le cahier de continuité","Les images-clés","L’animation plan par plan","Le son","Montage et étalonnage","Livrer et protéger"],"en":["Writing for AI","Character and set bibles","Shot list and continuity log","Key frames","Shot-by-shot animation","Sound","Editing and grading","Delivering and protecting"]},"outcomes":{"fr":["Un pack film archivé","Les prompts de chaque étape","Les droits sur voix et visages"],"en":["An archived film pack","The prompts for each step","Rights over voices and faces"]},"photo":"local:podcast-studio","lessons":[{"title":{"fr":"Écrire en plans de 4 secondes","en":"Writing in 4-second shots"},"copy":{"fr":"Un plan, une action, une idée. Les émotions en gros plan, l’action en plan large, et des ellipses pour ce qui coûte cher. 90 secondes, c’est 20 à 25 plans.","en":"One shot, one action, one idea. Emotions in close-up, action in wide shots, ellipses for what is costly. 90 seconds is 20 to 25 shots."},"exercise":{"fr":"Découpez une scène d’une minute en plans de 4 secondes.","en":"Break a one-minute scene into 4-second shots."},"question":{"fr":"Combien de plans pour 90 secondes ?","en":"How many shots for 90 seconds?"},"options":{"fr":["20 à 25","3","200"],"en":["20 to 25","3","200"]},"answer":0},{"title":{"fr":"Les quatre continuités","en":"The four continuities"},"copy":{"fr":"Personnage, décor, lumière et sens de l’écran doivent tenir d’un plan à l’autre. Les bibles et le cahier de continuité les verrouillent avant la génération.","en":"Character, set, light and screen direction must hold from shot to shot. Bibles and the continuity log lock them in before generation."},"exercise":{"fr":"Rédigez la bible d’un personnage et d’un décor.","en":"Write a character bible and a set bible."},"question":{"fr":"Quand verrouille-t-on la continuité ?","en":"When is continuity locked?"},"options":{"fr":["Avant la génération","Au montage seulement","Jamais"],"en":["Before generation","Only in the edit","Never"]},"answer":0},{"title":{"fr":"Le budget de génération","en":"The generation budget"},"copy":{"fr":"Un quart du temps en préparation, la moitié en génération, un quart en finition. Comptez 4 à 6 générations par plan retenu, davantage en gros plan.","en":"A quarter of the time in preparation, half in generation, a quarter in finishing. Count 4 to 6 generations per shot kept, more for close-ups."},"exercise":{"fr":"Estimez le budget de génération de votre film.","en":"Estimate your film’s generation budget."},"question":{"fr":"Combien de générations par plan retenu ?","en":"How many generations per shot kept?"},"options":{"fr":["4 à 6","1","50"],"en":["4 to 6","1","50"]},"answer":0}]}]'::jsonb) on conflict do nothing;
insert into public.content_collections(segment,collection,items) values('academy','offers','[{"slug":"parcours-complet","title":{"fr":"Parcours complet marketing digital","en":"Full digital marketing track"},"format":{"fr":"8 modules · 11 jours · 77 h","en":"8 modules · 11 days · 77 h"},"copy":{"fr":"Du fondamental à l’expert : stratégie, rédaction, Canva, Meta, vidéo, IA, prompts et gestion de crise.","en":"From foundation to expert: strategy, writing, Canva, Meta, video, AI, prompts and crisis management."},"photo":"local:academy-room"},{"slug":"parcours-institutionnel","title":{"fr":"Parcours communication institutionnelle","en":"Institutional communication track"},"format":{"fr":"8 semaines · 3 jours par semaine · 64 h","en":"8 weeks · 3 days a week · 64 h"},"copy":{"fr":"Conçu pour les cadres d’administrations et d’institutions : séances de 1 à 3 h, évaluation finale et remise des certificats.","en":"Designed for managers in administrations and institutions: 1- to 3-hour sessions, a final assessment and certificates."},"photo":"local:academy-teacher"},{"slug":"intensif-equipe","title":{"fr":"Intensif création de contenu & IA","en":"Content creation & AI intensive"},"format":{"fr":"3 semaines · 6 séances de 2 h","en":"3 weeks · 6 sessions of 2 h"},"copy":{"fr":"Pour les équipes marketing et communication : visuels, vidéo mobile, plan de contenu et usage encadré de l’IA.","en":"For marketing and communication teams: visuals, mobile video, content planning and supervised AI use."},"photo":"local:academy-class"},{"slug":"sur-mesure","title":{"fr":"Formation sur mesure","en":"Tailored training"},"format":{"fr":"Présentiel, en ligne ou hybride","en":"In person, online or hybrid"},"copy":{"fr":"Nous composons le programme à partir de vos outils, de votre niveau et des résultats attendus.","en":"We build the programme around your tools, your level and the results you expect."},"photo":"local:team-table"}]'::jsonb) on conflict do nothing;
